mapper.select:
SELECT id, city, pollutant_type AS pollutantType, value AS concentration, unit, date, create_time AS createTime
FROM pollutant_data


        AND city LIKE CONCAT('%', #{dto.city}, '%')


        AND pollutant_type = #{dto.pollutantType}


        AND date >= #{dto.startDate}


        AND date <= #{dto.endDate}


ORDER BY date DESC, value DESC
LIMIT 10000

SELECT DATE_FORMAT(date, '%Y-%m-%d') AS date, value AS value
FROM pollutant_data
WHERE city = #{city}
AND pollutant_type = #{pollutantType}
ORDER BY date DESC
LIMIT #{days}

SELECT pollutant_type AS name, AVG(value) AS value
FROM pollutant_data


        AND city = #{city}


        AND date >= #{startDate}


        AND date <= #{endDate}


GROUP BY pollutant_type
ORDER BY value DESC

SELECT pollutant_type AS pollutantType, value AS value, unit
FROM pollutant_data
WHERE city = #{city}
AND date = #{date}
AND pollutant_type IN

    #{pollutant}

ORDER BY value DESC

SELECT id, city, pollutant_type AS pollutantType, value AS concentration, unit, date, create_time AS createTime FROM pollutant_data WHERE date = (SELECT MAX(date) FROM pollutant_data)
AND city = #{city}
ORDER BY value DESC
